mapper.select:
SELECT b.id, b.transaction_type, b.category_id, c.name AS category_name, b.amount, b.transaction_date, b.remark, b.mood, b.created_at, b.updated_at FROM bills b INNER JOIN categories c ON c.id = b.category_id WHERE b.user_id = #{userId}
AND b.transaction_date >= #{startDate}
AND b.transaction_date < #{endDate}
AND b.transaction_type = #{transactionType}
AND b.category_id = #{categoryId}
ORDER BY b.transaction_date DESC, b.id DESC

mapper.update:
UPDATE bills
SET
category_id = #{bill.categoryId},
transaction_type = #{bill.transactionType},
amount = #{bill.amount},
transaction_date = #{bill.transactionDate},
remark = #{bill.remark},
mood = #{bill.mood}
WHERE id = #{bill.id}
AND user_id = #{bill.userId}

mapper.delete:
DELETE FROM bills
WHERE id = #{id}
AND user_id = #{userId}
